      "default": false
    },
    "keep": {
      "type": "string",
      "title": "Always keep",
      "description": "Comma-separated skill names or prefixes ending in * that are never dropped (e.g. operation-*, persona-define)",
      "default": ""
    },
    "drop": {
      "type": "string",
      "title": "Always drop",
      "description": "Comma-separated skill names or prefixes ending in * that are always dropped; keep wins over drop",
      "default": ""
    }
  }
}

